CREATE TABLE accounts (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,account_code VARCHAR(6) NOT NULL,name_ar VARCHAR(190) NOT NULL,name_en VARCHAR(190) NOT NULL,parent_id BIGINT UNSIGNED NULL,account_type VARCHAR(20) NOT NULL,normal_balance VARCHAR(10) NOT NULL,is_postable TINYINT(1) NOT NULL DEFAULT 0,is_control TINYINT(1) NOT NULL DEFAULT 0,is_active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_accounts_code(account_code),KEY idx_accounts_parent(parent_id),KEY idx_accounts_flags(is_active,is_postable,is_control),CONSTRAINT fk_accounts_parent FOREIGN KEY(parent_id) REFERENCES accounts(id) ON DELETE RESTRICT,CONSTRAINT chk_accounts_code CHECK(account_code REGEXP '^[0-9]{6}$'),CONSTRAINT chk_accounts_type CHECK(account_type IN('asset','liability','equity','revenue','expense')),CONSTRAINT chk_accounts_balance CHECK(normal_balance IN('debit','credit')),CONSTRAINT chk_accounts_parent_postable CHECK(parent_id IS NOT NULL OR is_postable=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
